// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Client project session – a framework-free state machine that owns the live document, its revision,
//          the debounced save queue, retries, conflicts, status and the per-project view state.

import type { DraftRecord, DraftState, ProjectRecord } from '#/server/projects.server'
import type { ProjectData, ProjectView } from './project'
import { TransportError, type CallOptions, type DraftOpening, type ProjectTransport } from './projectTransport'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human sees and opens drafts"
// Changes: A session can be opened on a draft: the draft's parts over the project's export naming and inputs.
import { PARTS, partEquals, readParts, writeParts, type PartName, type Parts } from './parts'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: Open drafts are editable: the human's changed parts are saved per part (the server merges a stale save
//          unless the same part changed), export naming and simulation inputs go to the project, and the session
//          polls the draft while the page is visible, applying remote changes to parts the human has not touched.
import { readSettings, settingsEqual, writeSettings } from './projectSettings'

const READ_ONLY_MESSAGE = 'Návrh je ukončený – nedá sa meniť.'
const DRAFT_IMPORT_MESSAGE = 'Do návrhu sa nedá importovať – importuj do projektu.'
/** How often an open, visible draft is fetched again. */
export const DRAFT_POLL_MS = 3_000

/**
 * saved/pending/saving – normal cycle; retrying – transient failure, will retry by itself;
 * failed – the server rejected the save (see `error`), retried a few times then left until the next edit;
 * conflict – another tab/colleague saved first (see `conflict`), nothing is saved until resolveConflict();
 * missing – the project was deleted elsewhere, local edits are kept but cannot be saved.
 */
export type SaveStatus = 'saved' | 'pending' | 'saving' | 'retrying' | 'failed' | 'conflict' | 'missing'

export interface SessionState {
  data: ProjectData
  view: ProjectView
  status: SaveStatus
  /** Something (document or view) is not yet on the server. */
  unsaved: boolean
  /** Message of the last failed save (status retrying/failed). */
  error: string | null
  /** The newer server version our save collided with. */
  conflict: ProjectRecord | null
  /** In a draft: the parts changed both by the human (unsaved) and by someone else (empty otherwise). */
  conflictParts: PartName[]
  savedAt: string
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Human sees and opens drafts"
  // Changes: The open draft (null = the project itself) and whether the document may be edited.
  /** The draft this session shows; null when it shows the project. */
  draft: DraftRecord | null
  /** Edits are ignored (the UI shows no editing controls). */
  readOnly: boolean
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Adopt and discard in the editor"
// Changes: What adopting returns to the UI: the updated project, or the fresh project when the adoption was refused.
export type AdoptOutcome = { status: 'adopted' | 'stale'; project: ProjectRecord }

export interface Timers {
  setTimeout: (fn: () => void, ms: number) => unknown
  clearTimeout: (handle: unknown) => void
}

const DEBOUNCE_MS = 600
const RETRY_BASE_MS = 5_000
const RETRY_MAX_MS = 60_000
/** Attempts of a save the server rejected (not transient) before waiting for the next edit. */
const REJECTED_ATTEMPTS = 3

// Saves still running per project id – also those of sessions already disposed (the editor was left).
const running = new Map<string, Set<Promise<unknown>>>()

function track(projectId: string, promise: Promise<unknown>) {
  const set = running.get(projectId) ?? new Set()
  running.set(projectId, set)
  const done = promise.catch(() => {})
  set.add(done)
  void done.then(() => {
    set.delete(done)
    if (!set.size) running.delete(projectId)
  })
}

/**
 * Resolves once no save of this project is running. The route loader awaits it before fetching, so coming back
 * to a project right after leaving it loads the revision the last save produced (instead of self-conflicting).
 */
export async function savesSettled(projectId: string): Promise<void> {
  for (let set = running.get(projectId); set?.size; set = running.get(projectId)) await Promise.all(set)
}

/** Opens a session on a project (its record) or on a draft (the draft and its project). */
export function createProjectSession(opening: ProjectRecord | DraftOpening, transport: ProjectTransport, timers: Timers = defaultTimers()) {
  const initial = 'draft' in opening ? opening.project : opening
  const draft = 'draft' in opening ? opening.draft : null
  let readOnly = draft !== null && draft.state !== 'open'
  let state: SessionState = {
    // A draft holds only the four parts; export naming and simulation inputs are always the project's.
    data: draft ? writeParts(initial.data, draft.parts) : initial.data,
    draft,
    readOnly,
    view: initial.view,
    status: 'saved',
    unsaved: false,
    error: null,
    conflict: null,
    conflictParts: [],
    savedAt: draft?.updatedAt ?? initial.updatedAt,
  }
  // The project's revision, or in a draft the draft's revision (the base of the next per-part save).
  let revision = draft?.revision ?? initial.revision
  let timer: unknown
  // Every edit bumps `editSeq`; the document is persisted when `savedSeq` caught up with it.
  let editSeq = 0
  let savedSeq = 0
  let inFlight: Promise<void> | null = null
  // Saving is impossible until the user acts (conflict, or the project was deleted elsewhere).
  let missing = false
  let conflict: ProjectRecord | null = null
  const blocked = () => missing || conflict !== null
  // Failed attempts in a row (reset by success and by a new edit after giving up).
  let failures = 0
  let lastFailure: TransportError | null = null

  // View state: its own debounced queue, no revision (last write wins), never blocks or conflicts.
  let viewSeq = 0
  let viewSavedSeq = 0
  let viewInFlight: Promise<void> | null = null
  let viewTimer: unknown
  let viewFailures = 0

  const dirty = () => editSeq !== savedSeq
  const viewDirty = () => viewSeq !== viewSavedSeq
  const listeners = new Set<() => void>()
  const set = (patch: Partial<SessionState>) => {
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
    // Changes: Only document edits count as unsaved (arms the leave-page prompt); view state is flushed on page hide.
    const next = { ...state, ...patch, unsaved: dirty() }
    if (Object.keys(next).every((k) => next[k as keyof SessionState] === state[k as keyof SessionState])) return
    state = next
    listeners.forEach((l) => l())
  }

  let disposed = false
  const schedule = (ms: number) => {
    timers.clearTimeout(timer)
    if (disposed) return
    timer = timers.setTimeout(() => void flush(), ms)
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Human edits drafts"
  // Changes: Draft mode – what the server has (the draft's parts at `revision`, the project's settings), so local
  //          changes are exactly the parts/settings that differ from it.
  let serverParts: Parts | null = draft && readParts(state.data)
  let serverSettings = readSettings(state.data)
  let conflictDraft: DraftRecord | null = null
  const changedLocally = (data: ProjectData, base: Parts) => PARTS.filter((part) => !partEquals(part, data, writeParts(data, base)))
  const unsavedLocally = () =>
    changedLocally(state.data, serverParts!).length > 0 || !settingsEqual(readSettings(state.data), serverSettings)

  /** Take a newer server draft: parts that `keep` says are the human's stay local, the others become the server's. */
  const rebase = (next: DraftRecord, keep: (part: PartName) => boolean) => {
    const data = PARTS.reduce((d, part) => (keep(part) ? d : writeParts(d, { [part]: next.parts[part] })), state.data)
    serverParts = next.parts
    revision = next.revision
    set({ data, draft: next })
  }

  const enterConflict = (next: DraftRecord, parts: PartName[]) => {
    timers.clearTimeout(timer)
    conflictDraft = next
    conflict = { ...initial, data: writeParts(state.data, next.parts), revision: next.revision, updatedAt: next.updatedAt }
    set({ status: 'conflict', conflict, conflictParts: parts })
  }

  // The draft was adopted or discarded elsewhere: nothing can be saved into it any more.
  const endDraft = (ended: DraftRecord) => {
    timers.clearTimeout(timer)
    stopPolling()
    readOnly = true
    savedSeq = editSeq
    set({ readOnly: true, draft: ended, status: 'saved', error: null })
  }

  const saveDraftOnce = async (opts?: CallOptions) => {
    const seq = editSeq
    const data = state.data
    set({ status: 'saving' })
    try {
      const settings = readSettings(data)
      if (!settingsEqual(settings, serverSettings)) {
        const res = await transport.saveSettings({ id: initial.id, settings }, opts)
        if (res.status === 'missing') return void (missing = true)
        serverSettings = settings
        set({ savedAt: res.updatedAt })
      }
      const sent = readParts(data)
      const changed = changedLocally(data, serverParts!)
      if (changed.length) {
        const parts = Object.fromEntries(changed.map((part) => [part, sent[part]])) as Partial<Parts>
        const res = await transport.saveDraft({ draftId: draft!.id, parts, baseRevision: revision }, opts)
        if (res.status === 'missing') return void (missing = true)
        if (res.status === 'ended') return endDraft(res.draft)
        if (res.status === 'conflict') return enterConflict(res.draft, res.parts)
        // The merged draft: parts edited again while saving stay local, everything else is the server's.
        rebase(res.draft, (part) => !partEquals(part, state.data, writeParts(state.data, sent)))
        set({ savedAt: res.draft.updatedAt })
      }
      failures = 0
      lastFailure = null
      savedSeq = seq
    } catch (err) {
      failures++
      lastFailure = err instanceof TransportError ? err : new TransportError(err instanceof Error ? err.message : String(err), true)
    }
  }

  const saveOnce = async (opts?: CallOptions) => {
    if (draft) return saveDraftOnce(opts)
    const seq = editSeq
    const data = state.data
    set({ status: 'saving' })
    try {
      const res = await transport.save({ id: initial.id, data, baseRevision: revision }, opts)
      failures = 0
      lastFailure = null
      if (res.status === 'saved') {
        revision = res.revision
        savedSeq = seq
        set({ savedAt: res.updatedAt })
      } else if (res.status === 'conflict') conflict = res.project
      else missing = true
    } catch (err) {
      failures++
      lastFailure = err instanceof TransportError ? err : new TransportError(err instanceof Error ? err.message : String(err), true)
    }
  }

  const flush = async (opts?: CallOptions): Promise<void> => {
    timers.clearTimeout(timer)
    if (inFlight) {
      await inFlight
      return flush(opts)
    }
    if (blocked() || !dirty()) return
    inFlight = saveOnce(opts)
    track(initial.id, inFlight)
    await inFlight
    inFlight = null
    if (missing) set({ status: 'missing' })
    else if (conflict) set({ status: 'conflict', conflict })
    else if (readOnly) return
    else if (lastFailure) {
      const giveUp = !lastFailure.retryable && failures >= REJECTED_ATTEMPTS
      set({ status: lastFailure.retryable ? 'retrying' : 'failed', error: lastFailure.message })
      if (!giveUp) schedule(Math.min(RETRY_BASE_MS * 2 ** (failures - 1), RETRY_MAX_MS))
    } else if (dirty()) {
      set({ status: 'pending' })
      schedule(DEBOUNCE_MS)
    } else set({ status: 'saved', error: null })
  }

  /** Replace the local document by a server record (local edits are gone – callers make sure that is intended). */
  const adopt = (record: ProjectRecord) => {
    timers.clearTimeout(timer)
    revision = record.revision
    savedSeq = editSeq
    conflict = null
    failures = 0
    lastFailure = null
    set({ data: record.data, status: 'saved', error: null, conflict: null, savedAt: record.updatedAt })
  }

  const scheduleView = (ms: number) => {
    timers.clearTimeout(viewTimer)
    if (!disposed) viewTimer = timers.setTimeout(() => void flushView(), ms)
  }

  const flushView = async (opts?: CallOptions): Promise<void> => {
    timers.clearTimeout(viewTimer)
    if (viewInFlight) {
      await viewInFlight
      return flushView(opts)
    }
    if (!viewDirty()) return
    const seq = viewSeq
    let retryIn = 0
    viewInFlight = (async () => {
      try {
        await transport.saveView({ id: initial.id, view: state.view }, opts)
        viewSavedSeq = seq
        viewFailures = 0
      } catch (err) {
        viewFailures++
        const retryable = !(err instanceof TransportError) || err.retryable
        // It is only UI state: after a few rejected attempts stop insisting (and stop the unload warning).
        if (!retryable && viewFailures >= REJECTED_ATTEMPTS) viewSavedSeq = seq
        else retryIn = Math.min(RETRY_BASE_MS * 2 ** (viewFailures - 1), RETRY_MAX_MS)
      }
    })()
    track(initial.id, viewInFlight)
    await viewInFlight
    viewInFlight = null
    set({})
    if (retryIn) scheduleView(retryIn)
    else if (viewDirty()) scheduleView(DEBOUNCE_MS)
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Human edits drafts"
  // Changes: Polling an open draft while the page is visible (and the editor mounted); skipped while a save runs or
  //          a conflict waits. A remote change of a part the human also changed unsaved is a conflict right away.
  let pollTimer: unknown = null
  let hidden = false
  const stopPolling = () => {
    timers.clearTimeout(pollTimer)
    pollTimer = null
  }
  const schedulePoll = (ms = DRAFT_POLL_MS) => {
    stopPolling()
    if (draft && !readOnly && !disposed && !hidden) pollTimer = timers.setTimeout(() => void poll(), ms)
  }
  const poll = async () => {
    if (!inFlight && !blocked()) {
      try {
        const opening = await transport.loadDraft({ draftId: draft!.id })
        if (!inFlight && !blocked()) applyRemote(opening)
      } catch {
        // Offline for a moment – the next poll tries again.
      }
    }
    if (pollTimer !== null) schedulePoll()
  }
  const applyRemote = (opening: DraftOpening | null) => {
    if (!opening) {
      missing = true
      stopPolling()
      return set({ status: 'missing' })
    }
    const next = opening.draft
    if (next.state !== 'open') return endDraft(next)
    // Settings the human is not editing follow the project.
    const remoteSettings = readSettings(opening.project.data)
    if (settingsEqual(readSettings(state.data), serverSettings) && !settingsEqual(remoteSettings, serverSettings)) {
      serverSettings = remoteSettings
      set({ data: writeSettings(state.data, remoteSettings) })
    }
    if (next.revision <= revision) return
    const mine = changedLocally(state.data, serverParts!)
    const overlap = mine.filter((part) => next.partRevisions[part] > revision && !partEquals(part, state.data, writeParts(state.data, next.parts)))
    if (overlap.length) return enterConflict(next, overlap)
    rebase(next, (part) => mine.includes(part))
    if (!dirty()) set({ status: 'saved' })
    void transport.markDraftViewed({ draftId: next.id, revision: next.revision }).catch(() => {})
  }


  // Persist local edits or explain (in Slovak, for a toast) why the caller must not go on.
  const ensureSaved = async () => {
    if (readOnly) throw new Error(READ_ONLY_MESSAGE)
    await flush()
    if (conflict) throw new Error('Najprv vyrieš konflikt verzií – tvoje zmeny zatiaľ nie sú uložené.')
    if (missing) throw new Error('Projekt bol medzitým zmazaný – tvoje zmeny nie je kam uložiť.')
    if (dirty()) {
      const reason = lastFailure ? ` (${lastFailure.message})` : ''
      throw new Error(`Neuložené zmeny sa nepodarilo uložiť${reason}. Skús to znova o chvíľu.`)
    }
  }

  // Run a server call that replaces the document; it occupies the save slot so no save overlaps it.
  const replaceWith = async (call: () => Promise<ProjectRecord | null>, goneMessage: string) => {
    await ensureSaved()
    const seq = editSeq
    let result: ProjectRecord | null = null
    const op = (async () => {
      result = await call()
    })()
    inFlight = op.catch(() => {})
    track(initial.id, inFlight)
    try {
      await op
    } finally {
      inFlight = null
    }
    const record = result as ProjectRecord | null
    if (!record) throw new Error(goneMessage)
    if (editSeq === seq) return adopt(record)
    // The user typed while the server replaced the document: keep both and let them choose.
    conflict = record
    set({ status: 'conflict', conflict: record })
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Draft history"
  // Changes: In a draft session named versions and restores go to the draft's own history; a restored draft replaces
  //          what the view shows. A read-only draft has nothing local to save first.
  const draftHistoryReady = () => (readOnly ? Promise.resolve() : ensureSaved())
  const adoptDraft = (record: DraftRecord) => {
    timers.clearTimeout(timer)
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Human edits drafts"
    // Changes: The restored draft is the new server baseline of per-part saves.
    serverParts = record.parts
    revision = record.revision
    conflictDraft = null
    savedSeq = editSeq
    conflict = null
    failures = 0
    lastFailure = null
    set({ draft: record, data: writeParts(state.data, record.parts), status: 'saved', error: null, conflict: null, conflictParts: [], savedAt: record.updatedAt })
  }
  const restoreDraftVersion = async (draftId: string, snapshotId: number) => {
    await draftHistoryReady()
    const restored = await transport.restoreDraft({ draftId, snapshotId })
    if (!restored) throw new Error('Verzia už neexistuje')
    adoptDraft(restored)
  }
  const saveDraftVersion = async (draftId: string, label: string) => {
    await draftHistoryReady()
    const snapshot = await transport.createDraftSnapshot({ draftId, label })
    if (!snapshot) throw new Error('Návrh už neexistuje')
    return snapshot
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Adopt and discard in the editor"
  // Changes: Ending the open draft. Adopting saves the human's edits into the draft first (they are adopted too) and
  //          occupies the save slot; a stale project refuses and hands back the fresh project for the dialog. Discarding
  //          saves what it can first (kept in the final snapshot). An ended draft makes the view read-only.
  const endedMessage = (ended: DraftState) => `Návrh je už ukončený (${ended === 'adopted' ? 'prevzatý' : 'zahodený'}).`
  const exclusive = async <T>(call: () => Promise<T>): Promise<T> => {
    const op = call()
    inFlight = op.then(() => {}, () => {})
    track(initial.id, inFlight)
    try {
      return await op
    } finally {
      inFlight = null
    }
  }
  const openDraftId = () => {
    if (!draft) throw new Error('Toto nie je návrh.')
    if (readOnly) throw new Error(endedMessage(state.draft!.state))
    return draft.id
  }
  const adoptParts = async (parts: PartName[], projectRevision: number): Promise<AdoptOutcome> => {
    const draftId = openDraftId()
    await ensureSaved()
    const result = await exclusive(() => transport.adoptDraft({ draftId, parts, projectRevision }))
    if (result.status === 'missing') throw new Error('Návrh už neexistuje')
    if (result.status === 'stale') return { status: 'stale', project: result.project }
    endDraft(result.draft)
    if (result.status === 'ended') throw new Error(endedMessage(result.draft.state))
    return { status: 'adopted', project: result.project }
  }
  const discardOpenDraft = async () => {
    const draftId = openDraftId()
    await flush()
    const result = await exclusive(() => transport.discardDraft({ draftId }))
    if (result.status === 'missing') throw new Error('Návrh už neexistuje')
    endDraft(result.draft)
    if (result.status === 'ended') throw new Error(endedMessage(result.draft.state))
  }

  return {
    /** Immutable snapshot – a new object whenever anything changed (fits useSyncExternalStore). */
    getState: () => state,
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => void listeners.delete(listener)
    },
    /** Save pending edits now; resolves true when everything is on the server. */
    async flushNow() {
      await Promise.all([flush(), flushView()])
      return !dirty()
    },
    /** The page is being hidden or closed: save everything now, in requests that may outlive the page. */
    pageHidden() {
      hidden = true
      stopPolling()
      const opts = { keepalive: true }
      void flush(opts)
      void flushView(opts)
    },
    /** The page is visible again: refresh an open draft at once and keep polling. */
    pageShown() {
      hidden = false
      if (draft && !disposed && !readOnly) schedulePoll(0)
    },
    /** Change the per-project view state (saved debounced, independent of the document). */
    updateView(fn: (v: ProjectView) => ProjectView) {
      viewSeq++
      set({ view: fn(state.view) })
      if (!viewInFlight && !viewFailures) scheduleView(DEBOUNCE_MS)
    },
    /** A record fetched again (route loader). Adopted only when newer and nothing local is pending. */
    receive(record: ProjectRecord) {
      if (!viewDirty() && !viewInFlight) set({ view: record.view })
      // A draft's content does not come from the project record.
      if (draft) return
      if (record.revision <= revision || dirty() || inFlight || blocked()) return
      adopt(record)
    },
    /** The editor goes away: save what is pending right now (tracked by savesSettled) and stop timers. */
    dispose() {
      disposed = true
      stopPolling()
      timers.clearTimeout(timer)
      timers.clearTimeout(viewTimer)
      track(initial.id, Promise.all([flush(), flushView()]))
    },
    /** Undo dispose() when React mounts the same editor again (StrictMode, Activity). */
    resume() {
      disposed = false
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "Human sees and opens drafts"
      // Changes: Showing a draft records it as viewed by the human (clears "updated by agent"); best effort.
      if (draft?.state === 'open') void transport.markDraftViewed({ draftId: draft.id, revision: draft.revision }).catch(() => {})
      if (dirty() && !blocked() && !inFlight) schedule(DEBOUNCE_MS)
      if (viewDirty() && !viewInFlight) scheduleView(DEBOUNCE_MS)
      schedulePoll()
    },
    /** Restore a snapshot (the server stores the current state in history first). */
    restoreVersion: (snapshotId: number) =>
      draft ? restoreDraftVersion(draft.id, snapshotId) : replaceWith(() => transport.restore({ id: initial.id, snapshotId }), 'Verzia už neexistuje'),
    /** Replace the document by imported data; `label` names the history entry of the current state. */
    importData: async (data: ProjectData, label: string) => {
      if (draft) throw new Error(readOnly ? READ_ONLY_MESSAGE : DRAFT_IMPORT_MESSAGE)
      return replaceWith(() => transport.replace({ id: initial.id, data, label }), 'Projekt už neexistuje')
    },
    /** Store the current (saved) state as a named version. */
    async saveNamedVersion(label: string) {
      if (draft) return saveDraftVersion(draft.id, label)
      await ensureSaved()
      const snapshot = await transport.createSnapshot({ id: initial.id, label })
      if (!snapshot) throw new Error('Projekt už neexistuje')
      return snapshot
    },
    /** theirs = load the server version (drops local edits); mine = overwrite the server with the local version. */
    async resolveConflict(choice: 'theirs' | 'mine') {
      if (!conflict) return
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "Human edits drafts"
      // Changes: In a draft only the conflicting parts are decided; the human's other edits are kept and saved.
      if (conflictDraft) {
        const next = conflictDraft
        const parts = state.conflictParts
        const mine = changedLocally(state.data, serverParts!)
        rebase(next, (part) => mine.includes(part) && (choice === 'mine' || !parts.includes(part)))
        conflict = conflictDraft = null
        if (!unsavedLocally()) savedSeq = editSeq
        set({ status: dirty() ? 'pending' : 'saved', conflict: null, conflictParts: [] })
        return flush()
      }
      if (choice === 'theirs') return adopt(conflict)
      revision = conflict.revision
      conflict = null
      set({ status: 'pending', conflict: null })
      await flush()
    },
    /**
     * Adopt the chosen parts of the open draft into the project. `projectRevision` is the project revision the human
     * decided on; when the project has moved since, nothing happens and the fresh project comes back (stale).
     */
    adopt: adoptParts,
    /** Discard the open draft (ends it; the project is untouched). */
    discard: discardOpenDraft,
    /** Change the document; saved after a short pause in editing. */
    edit(fn: (d: ProjectData) => ProjectData) {
      if (readOnly) return
      editSeq++
      // Not while blocked or a request runs (it reschedules), nor during a transient-failure backoff;
      // after a rejected save a new edit is a fresh round of attempts.
      const start = !blocked() && !inFlight && !lastFailure?.retryable
      if (start) failures = 0
      set({ data: fn(state.data), ...(start ? { status: 'pending' as const } : {}) })
      if (start) schedule(DEBOUNCE_MS)
    },
  }
}

function defaultTimers(): Timers {
  return {
    setTimeout: (fn, ms) => globalThis.setTimeout(fn, ms),
    clearTimeout: (h) => globalThis.clearTimeout(h as ReturnType<typeof setTimeout>),
  }
}
